/**
 * ResizablePanel — 可拖拽调整宽度的面板。
 *
 * 借鉴 deepseek-harness 的 AppFrame 拖拽分隔栏：
 * - pointer capture + rAF 节流
 * - 最小/最大宽度约束
 * - 自动折叠（窗口过窄时）
 */
import { useCallback, useEffect, useRef, useState } from 'react'
import { cn } from '@/lib/utils'

interface ResizablePanelProps {
  children: React.ReactNode
  initialWidth: number
  minWidth?: number
  maxWidth?: number
  side?: 'left' | 'right'
  collapsed?: boolean
  onCollapse?: (collapsed: boolean) => void
  className?: string
}

export function ResizablePanel({
  children,
  initialWidth,
  minWidth = 200,
  maxWidth = 500,
  side = 'left',
  collapsed = false,
  onCollapse,
  className,
}: ResizablePanelProps) {
  const [width, setWidth] = useState(initialWidth)
  const isDragging = useRef(false)
  const startX = useRef(0)
  const startWidth = useRef(0)
  const rafId = useRef<number>()

  const handlePointerDown = useCallback((e: React.PointerEvent) => {
    isDragging.current = true
    startX.current = e.clientX
    startWidth.current = width
    ;(e.target as HTMLElement).setPointerCapture(e.pointerId)
    document.body.style.cursor = 'col-resize'
    document.body.style.userSelect = 'none'
  }, [width])

  const handlePointerMove = useCallback((e: React.PointerEvent) => {
    if (!isDragging.current) return

    // rAF 节流
    if (rafId.current) return
    rafId.current = requestAnimationFrame(() => {
      const delta = side === 'left'
        ? e.clientX - startX.current
        : startX.current - e.clientX
      const newWidth = Math.min(maxWidth, Math.max(minWidth, startWidth.current + delta))
      setWidth(newWidth)
      rafId.current = undefined
    })
  }, [side, minWidth, maxWidth])

  const handlePointerUp = useCallback((e: React.PointerEvent) => {
    isDragging.current = false
    ;(e.target as HTMLElement).releasePointerCapture(e.pointerId)
    document.body.style.cursor = ''
    document.body.style.userSelect = ''

    // 自动折叠：拖到最小宽度以下
    if (width <= minWidth + 10 && onCollapse) {
      onCollapse(true)
    }
  }, [width, minWidth, onCollapse])

  // 窗口 resize 时自动折叠
  useEffect(() => {
    const checkWidth = () => {
      if (window.innerWidth < 768 && onCollapse) {
        onCollapse(true)
      }
    }
    window.addEventListener('resize', checkWidth)
    return () => window.removeEventListener('resize', checkWidth)
  }, [onCollapse])

  // 清理 rAF
  useEffect(() => {
    return () => {
      if (rafId.current) cancelAnimationFrame(rafId.current)
    }
  }, [])

  if (collapsed) return null

  return (
    <div
      className={cn('relative flex flex-col shrink-0', className)}
      style={{ width }}
    >
      {/* 内容 */}
      <div className="flex-1 overflow-hidden">{children}</div>

      {/* 拖拽手柄 */}
      <div
        className={cn(
          'absolute inset-y-0 z-10 w-1 cursor-col-resize transition-colors hover:bg-primary/30',
          side === 'left' ? 'right-0' : 'left-0',
        )}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
      />
    </div>
  )
}
